import type { Metadata } from 'next'
import { siteSettings } from '@/config/siteSettings'

export const SITE_NAME = 'Infinity Taekwondo'
export const SITE_URL = siteSettings.brand.canonicalDomain

/**
 * Social preview images (generated by app/opengraph-image.tsx and app/twitter-image.tsx).
 *
 * A page that sets its own `openGraph` or `twitter` metadata replaces the site-wide one entirely,
 * images included, so it must list these again; otherwise links to it share without a picture.
 * `pageMetadata` below always does.
 */
export const SHARE_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'Infinity Taekwondo Academy Phnom Penh',
}

export const TWITTER_IMAGE = '/twitter-image'

/** Every page is about the brand and the sport, taught in Phnom Penh, Cambodia. */
export const CORE_KEYWORDS = [
  'Infinity Taekwondo',
  'Infinity TKD',
  'Taekwondo',
  'Taekwondo Phnom Penh',
  'Taekwondo Cambodia',
  'World Taekwondo',
  'Kukkiwon',
]

/** Each library discipline as a word for titles: "Taegeuk 1 (Il Jang): Taekwondo Poomsae Guide". */
export const LIBRARY_DISCIPLINE: Record<string, string> = {
  poomsae: 'Poomsae',
  'kicking-fundamentals': 'Kick',
  'kicking-advanced': 'Kick',
  'hand-techniques': 'Hand Technique',
  stances: 'Stance',
  hosinsul: 'Self-Defense',
  'tricking-acrobatics': 'Tricking',
  history: 'History',
  'competition-rules': 'Rules',
}

/** Trims to a search-snippet length at a word boundary. */
export function snippet(text: string, max = 158): string {
  const clean = text.replace(/\s+/g, ' ').trim()
  if (clean.length <= max) return clean
  const cut = clean.slice(0, max - 1)
  return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:.\s]+$/, '')}…`
}

/** Search results show about 60 characters of a title and cut it off past about 70. */
export const TITLE_MAX = 70

export const withBrand = (title: string) => `${title} | ${SITE_NAME}`

/** "Roundhouse Kick (Dollyo Chagi)" -> "Roundhouse Kick". */
export const withoutAsides = (text: string) =>
  text
    .replace(/\s*\([^)]*\)/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim()

/** The usual fallbacks for a title: with the brand, without it, then without its bracketed asides. */
export const titleForms = (title: string) => [withBrand(title), title, withBrand(withoutAsides(title)), withoutAsides(title)]

/** The first candidate that fits in TITLE_MAX characters (else the shortest), so no title is cut mid-phrase. */
export function fitTitle(candidates: string[]): string {
  return candidates.find((c) => c.length <= TITLE_MAX) ?? candidates.reduce((best, c) => (c.length < best.length ? c : best))
}

type SeoImage = string | { url: string; width?: number; height?: number; alt?: string }

export interface PageSeo {
  /** Page title without the brand; " | Infinity Taekwondo" is added when the whole title still fits. */
  title: string
  /** Full titles to try in order (default: `titleForms(title)`); the first within TITLE_MAX wins. */
  titleCandidates?: string[]
  /** 120-160 characters: what the page offers, with "Taekwondo" and the brand in natural words. */
  description: string
  /** Path from the site root, e.g. "/academy" (becomes the canonical URL). */
  path: string
  /** Page-specific search phrases; the core brand and sport phrases are added automatically. */
  keywords?: string[]
  /** Social card image; defaults to the generated brand card. */
  image?: SeoImage
  type?: 'website' | 'article'
}

/**
 * Complete metadata for a page: title, description, keywords, canonical URL, and Open Graph and
 * Twitter cards that always carry the brand name and an image.
 */
export function pageMetadata({ title, titleCandidates, description, path, keywords = [], image, type = 'website' }: PageSeo): Metadata {
  const socialTitle = withBrand(title)
  return {
    title: { absolute: fitTitle(titleCandidates ?? titleForms(title)) },
    description,
    keywords: [...new Set([...keywords, ...CORE_KEYWORDS])],
    alternates: { canonical: path },
    openGraph: {
      title: socialTitle,
      description,
      url: path,
      siteName: SITE_NAME,
      locale: 'en_US',
      type,
      images: [image ?? SHARE_IMAGE],
    },
    twitter: {
      card: 'summary_large_image',
      title: socialTitle,
      description,
      images: [image ? (typeof image === 'string' ? image : image.url) : TWITTER_IMAGE],
    },
  }
}
